file.content:
  font-family: var(--family-ui);
  letter-spacing: 0.02em;
  text-align: left;
  cursor: pointer;
  transition:
    color var(--transition-fast),
    background-color var(--transition-fast);

  &:hover,
  &.is-active {
    color: #fff;
    background: color-mix(in srgb, var(--clr-white-100) 10%, transparent);
  }
}

@include mq-max(767) {
  &__bottom-controls {
    width: calc(100vw - 2rem);
    max-width: 26rem;
    gap: 0.625rem;
  }

  &__bottom-toggle,
  &__filter-wrap {
    flex: 1 1 0;
  }

  &__bottom-toggle,
  &__filter-button {
    min-width: 0;
  }

  &__filter-button {
    width: 100%;
  }

  &__filter-panel {
    width: 100%;
  }
}

&__grid {
  position: relative;
  z-index: var(--z-index-works-canvas);
  overflow: visible;
  pointer-events: auto;
  min-height: calc(100vh - var(--header-height));
  padding: var(--gutter-2xl) 0;
  background: transparent;
  transition: opacity var(--transition-default);

  .no-works-canvas[data-view="scatter"] & {
    position: fixed;
    inset: 0;
    overflow: auto;
    margin-top: var(--header-height);
    min-height: 0;
  }

  &.is-hidden {
    display: none !important;
  }

  &:not(.is-hidden) {
    display: block;
  }

  &.is-transitioning-in {
    opacity: 1;
  }

  .no-sub-works {
    margin-top: 0;
    padding-top: 0;
  }

  .no-works-canvas__grid-badge,
  .no-works-canvas__grid-link {
    @include font("f-body-4");
    font-family: var(--family-ui);

