.no-sub-works {
  $root: &;
  margin-top: var(--header-height);
  padding-top: fluid(64, 128);

  &__gallery {
    padding-right: var(--gutter-lg);
    &-list {
      position: relative;
    }
    &-item {
      width: 48%;
      display: flex;
      flex-direction: column;
      &:nth-child(even) {
        margin-left: auto;
        margin-top: -24rem;
      }
      &:nth-child(odd) {
        margin-right: auto;
      }
      & > .no-works-canvas__grid-link {
        margin-top: var(--gutter-sm);
        align-self: flex-start;
      }
      &__img {
        margin: 0;
        @include img-auto-cover(62.5%);

        img,
        video {
          @include img-cover;
          transition: transform var(--transition-default);
        }
      }

      &__img-wrap {
        position: relative;
        padding: var(--gutter-xs);
        border: 1px solid var(--clr-border-default);
      }

      &__corner {
        color: color-mix(in srgb, var(--clr-white-100) 72%, transparent);
      }

      &__img-inner {
        overflow: hidden;
      }

      &__link {
        display: block;
        color: inherit;
        text-decoration: none;

        &:hover {
          #{$root}__gallery-item__img-inner img,
          #{$root}__gallery-item__img-inner video {
            transform: scale(1.08);
          }
        }
      }

      &__body {
        margin-top: var(--gutter-sm);
        display: flex;
        justify-content: space-between;
      }
      &__title {
        @include font("f-heading-3");
        font-weight: 700;
      }
      &__info {
        display: flex;
        margin-top: var(--gutter-sm);
        gap: var(--gutter-xs);
      }
    }
  }
  &__inner {
    display: grid;
    grid-template-columns: 3fr 9fr;
    gap: var(--gutter-md);
  }
  &__filter {
    position: sticky;
    left: 0;
    top: calc(var(--header-height) + var(--gutter-2xl));
    height: fit-content;
    z-index: var(--z-index-sticky-filter);
  }
  /* 그리드 카테고리 필터: rect는 기본 숨김, active·hover·focus 시에만 펄스 */
  &__filter-rect {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    flex-shrink: 0;

    span {
      width: fluid(3, 5);
      height: fluid(3, 5);
      background: currentColor;
      opacity: 0;
      animation: none;
    }
  }

  &__filter-item.active #{$root}__filter-rect,
  &__filter-button:hover #{$root}__filter-rect,
  &__filter-button:focus-visible #{$root}__filter-rect {
    span {
      animation: no-loop-filter-rect-pulse 1.2s linear infinite;
    }

    span:nth-child(1) {
      animation-delay: 0s;
    }

    span:nth-child(2) {
      animation-delay: 0.18s;
    }

    span:nth-child(3) {
      animation-delay: 0.54s;
    }

    span:nth-child(4) {
      animation-delay: 0.36s;
    }
  }
  &__filter-list {
    display: flex;
    flex-direction: column;
  }
  &__filter-button {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: fluid(4, 6);
    border: 0;
    background: transparent;
    color: var(--clr-text-body);
    font-family: var(--family-ui);
    opacity: 0.56;
    transition: opacity var(--transition-fast);
    cursor: pointer;
    a,
    button {
      @include font("f-body-2");
      font-family: var(--family-ui);
    }

    &::after {
      content: ".....[View]";
      margin-left: fluid(8, 12);
      display: inline-block;
      overflow: hidden;
      max-width: 0;
      opacity: 0;
      transform: translateY(0);
      pointer-events: none;
      color: var(--clr-text-desc);
      font-family: var(--family-ui);
      @include font("f-body-3");
      white-space: nowrap;
      border-right: 1px solid transparent;
      animation: none;
    }

    &:hover,
    &:focus-visible {

